#requires -Version 7.0
<#
VIA v0162B · 一鍵完整安裝與啟動 · One-file complete installer & launcher
=========================================================================
執行方式(PowerShell 7):
  pwsh -NoProfile -ExecutionPolicy Bypass -File "$HOME\Downloads\Install-VIA-v0162B-Complete.ps1"

此檔案會:
  1. 建立/使用 Base 資料夾(預設 C:\Users\tonyk\Downloads\VeritasIntelligenceAnalytics)
  2. 寫入 v0162B 完整套件的全部檔案(每一個都做 SHA-256 位元組驗證)
  3. 自動執行 StartVIASystemManager.ps1(精確 SHA 閘門 → AST 驗證 → AllInOne 三輪分析)

參數:
  -Base <路徑>   安裝目標(預設同上)
  -InstallOnly   只安裝檔案、不啟動系統

治理:僅寫入本套件自身的檔案;不觸碰 VRN / VDF / VAP 既有 canonical 內容。
#>
[CmdletBinding()]
param(
    [string]$Base = 'C:\Users\tonyk\Downloads\VeritasIntelligenceAnalytics',
    [switch]$InstallOnly
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Write-VIALog {
    param([Parameter(Mandatory)][string]$Message, [string]$Color = 'Gray')
    Write-Host ('[{0}] {1}' -f [DateTime]::Now.ToString('HH:mm:ss'), $Message) -ForegroundColor $Color
}

Write-Host ''
Write-Host 'VIA v0162B · ONE-FILE COMPLETE INSTALLER' -ForegroundColor Cyan
Write-Host ''

New-Item -ItemType Directory -Force -Path $Base | Out-Null
$Base = (Resolve-Path -LiteralPath $Base).Path
Write-VIALog -Message ('BASE : ' + $Base) -Color DarkCyan

