$installed = 0
foreach ($file in $Files) {
    $relative = [string]$file.Path
    $separator = [string][System.IO.Path]::DirectorySeparatorChar
    $target = Join-Path -Path $Base -ChildPath ($relative.Replace('/', $separator))
    $directory = Split-Path -Parent $target
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
    $clean = ([string]$file.Data) -replace '\s', ''
    $bytes = [System.Convert]::FromBase64String($clean)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    $actual = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne [string]$file.SHA) {
        throw ('SHA-256 mismatch for ' + $relative + '. Expected=' + $file.SHA + ' Actual=' + $actual)
    }
    Write-VIALog -Message ('OK  sha256-verified : ' + $relative) -Color Green
    $installed = $installed + 1
}

Write-Host ''
Write-VIALog -Message ('INSTALL COMPLETE : ' + $installed + ' files, all SHA-256 verified.') -Color Cyan

if ($InstallOnly.IsPresent) {
    Write-VIALog -Message '-InstallOnly: skipping launch. Run StartVIASystemManager.ps1 anytime.' -Color Yellow
    return
}

Write-Host ''
Write-VIALog -Message 'Launching VIA System Manager (exact-SHA gate + AST validation + 3-round analysis)...' -Color Cyan
& (Join-Path -Path $Base -ChildPath 'StartVIASystemManager.ps1')

